function dictionaryPage(){return `<div class="notice">指标口径 ${UE_VERSION}。正式收入确认、补贴归属、成本范围和审批额度待财务与业务确认。</div>`+
  `<div class="dictionary">${panel('平台单均收益：平台每单赚多少',`<div class="panel-body"><div class="equation">佣金与技术服务费 + 商家配送服务费 + 顾客配送费 + 推广广告 + 其他收入<br>− 骑手配送 − 平台用户补贴 − 骑手补贴 − 支付客服等变动成本</div><p class="subtitle">总部、研发、管理等固定成本单列，不能把单均收益当作净利润。</p></div>`)}${panel('商家单均收益：商家供货能否持续',`<div class="panel-body"><div class="equation">账单结算金额<br>− 食材 − 包装成本 − 退款赔付 − 增量人工</div><p class="subtitle">结算已扣的佣金、配送服务费、推广和商家补贴不重复扣。顾客包装费收入与包装耗材成本分开。</p></div>`)}${panel('商品收益：哪个商品、哪个场景出问题',`<div class="panel-body"><div class="equation">一单一品：订单 UE = 商品 UE<br>一单多品：按参与范围、分摊比例、承担方分别落表</div><p class="subtitle">餐盒参与商品优惠分摊；袋费和配送费不进入商品基数。按分取整，尾差归最后一个参与商品。</p>${btn('allocation','查看分摊算例 →','','link')}</div>`)}</div>`+
  `<div style="height:20px"></div>`+panel('统一统计规则',table(['项目','本版规则','需要保留的证据'],[['统计范围','完成订单数；按下单日期统计；退款保留原订单，取消与未完成订单不计','订单状态、原订单号、退款记录'],['汇总','经营分组 → 商品 → 订单；按订单量加权，不取简单平均','完整订单清单及纳入条件'],['补贴承担','平台、商家、品牌三方分列；发起方与出资方分开','活动规则、分担和结算明细'],['金额符号','扣减项用正数记录，公式中明确相减；未知与真实的零分开','原值、币种、单位、数据来源版本'],['数据质量','实测 / 推算 / 估算 / 缺失；示例数据单独标注','系统、账单、数据来源版本、采集时间、凭据'],['基线与订单量','连续四周；经营分组至少 100 单；商品至少 30 单；不足时扩大范围或延长观察','统计范围、来源覆盖、订单量'],['补贴过度','平台单均收益为负，且每 1 元补贴带来的新增收益低于 1 元；补贴前已亏损的先查价格和成本','自然订单基线、增量贡献、补贴总费用'],['复购与健康订单','15 元以下订单占比、停补后 30 日复购、商家实收率与利润','用户身份去标识、完整观察期，缺失不猜'],['竞争比价','同店、同品同规格、同用户条件、5 分钟内、同履约方式和配送点位','资格、前端截图/文本、原始时间与入口']].map(r=>`<tr>${r.map(c=>`<td class="wrap">${c}</td>`).join('')}</tr>`),900));}

function render(){app.innerHTML=`<header class="topbar"><a class="brand" href="#overview" data-action="nav" data-id="overview"><span class="brand-icon" aria-hidden="true"><i></i><i></i><i></i><i></i></span>包销品 UE</a><nav class="nav" aria-label="主导航">${Object.entries(pages).map(([k,l])=>`<button data-action="nav" data-id="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}>${l}${k==='execution'&&tasks.some(t=>t.status==='approval'&&match(skuById(t.skuId)))?` <span class="badge-count">${tasks.filter(t=>t.status==='approval'&&match(skuById(t.skuId))).length}</span>`:''}</button>`).join('')}</nav><div class="top-right">${(page==='data'&&['catalog','collect','records'].includes(dataTab)||page==='diagnosis'&&diagnosisSource==='actual')?'<span class="demo-tag">实际采集</span>':btn('about','示例数据','','demo-tag')}<select class="role" data-role aria-label="当前角色">${roles.map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select><span class="avatar">运</span></div></header><main class="workspace" id="main">${storageWarning?`<div class="notice red">${h(storageWarning)}</div>`:''}${({overview,diagnosis,strategy,execution,review,data:dataPage}[page])()}</main>`;}


function skuDrawer(id:string,tab=detailTab){selectedSku=id;detailTab=tab;const s=selected(),m=sm(s),d=diagnose(m,'sku',filters.days);
  const nav=`<div class="statusline"><span>${h(s.store)}</span><span>${s.id} · ${s.spec}</span></div><div class="tabs">${[['ledger','收益明细'],['competition','竞对同品'],['orders','订单与证据']].map(([k,l])=>btn('detail-tab',l!,k!,tab===k?'active':'')).join('')}</div>`;
  let body='';
  if(tab==='ledger'){
    const list=skuOrders(s).filter(o=>o.status==='completed'),avg=(f:(o:Order)=>number)=>m.n?list.reduce((a,o)=>a+f(o),0)/m.n:0;
    body=`<div class="kpis">${metricCard('平台单均收益',signed(m.platform),'',tone(m.platform))}${metricCard('商家单均收益',m.merchant===null?'未取得':money(m.merchant),'最低收益 ¥2.00/单',m.merchant!==null&&m.merchant<200?'negative':'positive')}${metricCard('完成订单',n(m.n),'四周订单')}${metricCard('补贴回报',m.roi?.toFixed(2)??'—','按历史订单估算','warning')}</div><div class="notice ${d==='structure'?'red':''}">${tag(labels[d],tones[d])}　${diagnosisAdvice(d)}。${m.merchant===null?'食材成本缺失，商家收益不能计算。':m.merchant<200?'同时触及商家收益底线，不能靠压低商家利润改善平台单均收益。':''}</div><div class="detail-grid">${panel('平台收入与支出 / 单均',`<div class="panel-body">${moneyRow('技术服务费与佣金',avg(o=>o.commission))}${moneyRow('商家配送服务费',avg(o=>o.merchantDelivery))}${moneyRow('顾客配送费',avg(o=>o.customerDelivery))}${moneyRow('推广广告与其他收入',avg(o=>o.advertising+o.otherRevenue))}${moneyRow('− 骑手配送与补贴',avg(o=>o.rider+o.riderSubsidy))}${moneyRow('− 支付、客服变动成本',m.validPlatform===m.n?avg(o=>o.variable!):null)}${moneyRow('补贴前收益',m.before,true)}${moneyRow('− 平台用户补贴',m.subsidy/m.n)}${moneyRow('补贴后平台单均收益',m.platform,true)}</div>`)}${panel('商家结算后收益 / 单均',`<div class="panel-body">${moneyRow('账单结算金额',avg(o=>o.settlement))}${moneyRow('− 食材成本',s.foodFen)}${moneyRow('− 包装耗材成本',avg(o=>o.packagingCost))}${moneyRow('− 退款与赔付',avg(o=>o.refund))}${moneyRow('− 增量人工',avg(o=>o.labor))}${moneyRow('商家单均收益',m.merchant,true)}<p class="subtitle">佣金、配送服务费及商家活动补贴已在结算中扣除，不在此处重复扣。退款不删除订单。</p></div>`)}</div><div style="height:18px"></div>${panel('健康订单与资金承担',`<div class="panel-body">${moneyRow('平台出资 / 总额',m.subsidy)}${moneyRow('商家出资 / 总额',m.merchantSubsidy)}${moneyRow('品牌出资 / 总额',m.brandSubsidy)}<div class="money-row"><span>15 元以下订单占比</span><span class="num">${pct(m.lowPrice,m.n)}</span></div><div class="money-row"><span>商家实收率（结算 / 商品及包装）</span><span class="num">${pct(list.reduce((a,o)=>a+o.settlement,0),m.gmv)}</span></div><div class="money-row"><span>停补后 30 日复购</span><span>未取得</span></div></div>`)}<div class="actions spread"><span></span>${btn('strategy-sku','制定调整方案 →',s.id,'primary',['insufficient','missing'].includes(d)||m.merchant===null||!classify(s).baoxiao)}</div>`;
  }else if(tab==='competition'){
    const qs=quotes(s);body=`<div class="comparison-date">报价时间：2026-11-06</div>`+table(['平台','结算应付','菜单标价','包装 / 配送','成交形态','观察时间','比价结果'],qs.map((q,i)=>{const c=compare(qs[0]!,q,m.n);return `<tr><td>${q.platform}</td><td class="num">${q.payable===null?'未取得':money(q.payable)}</td><td class="num">${money(q.menu)}</td><td class="num">${money(q.packaging)} / ${money(q.delivery)}</td><td>${forms[q.form]}</td><td class="num">${q.at.slice(11,19)}</td><td>${i===0?tag('我方基准','blue'):c.reasons.length?tag('不可比','amber'):`<span class="num">${c.index?.toFixed(3)??'指数不可算'}</span>`}</td></tr>`}),850)+qs.slice(1).map(q=>{const c=compare(qs[0]!,q,m.n);return panel(`${q.platform} · 对齐检查`,`<div class="panel-body"><ul class="list">${[['同一实体门店',q.store===qs[0]!.store&&q.address===qs[0]!.address,q.store+' / '+q.address],['同一商品、规格和数量',q.item===qs[0]!.item&&q.spec===qs[0]!.spec&&q.quantity===qs[0]!.quantity&&q.options===qs[0]!.options,q.item+' / '+q.spec+' / '+q.options],['同一用户与券资格',q.eligible&&q.user===qs[0]!.user,q.user],['同一时间窗口',Math.abs(Date.parse(q.at)-Date.parse(qs[0]!.at))<=300000,`${qs[0]!.at} / ${q.at}`],['同一履约方式和点位',q.fulfillment===qs[0]!.fulfillment&&q.point===qs[0]!.point,`${q.fulfillment} · ${q.point}`]].map(([l,ok,v])=>`<li class="checkline"><span class="${ok?'checkmark':'crossmark'}">${ok?'✓':'×'}</span><span>${l}：${h(v)}</span></li>`).join('')}</ul>${c.reasons.length?`<div class="notice red">${c.reasons.map(h).join('；')}。保留证据，不计算指数或价差。</div>`:`<div class="notice green">价差 ${signed(c.delta)} 元 · 相对价差 ${c.percent?.toFixed(2)??'不可算'}% · 我方与竞对价格比 ${c.index?.toFixed(3)??'不可算'}。</div>`}${c.differentForm?'<p class="subtitle">成交形态不同：京东直降，对方券后。价格位置可观察，不能把差额直接算作平台补贴。</p>':''}${btn('quote-evidence','查看报价明细',`${s.id}|${q.platform}`,'link')}</div>`);}).join('');
  }else{body=transactionSummary(s)+``+table(['订单号 / 日期','状态','成交形态','#顾客实付','#商家结算','#平台单均收益','凭据'],[...skuOrders(s,true).slice(0,7),...skuOrders(s,true).slice(-2)].map(o=>`<tr><td class="num">${o.id}<span class="secondary">${o.date}</span></td><td>${tag(o.status==='completed'?(o.refund?'完成 · 有售后退款':'完成'):o.status==='cancelled'?'取消':'已支付未完成',o.status==='completed'?'green':'gray')}</td><td>${forms[o.form]}</td><td class="number num">${money(o.paid)}</td><td class="number num">${money(o.settlement)}</td><td class="number num ${tone(ledger(o).platform)}">${o.status==='completed'?signed(ledger(o).platform):'不计入'}</td><td>${btn('order','查看',o.id,'link')}</td></tr>`),900)+`<p class="smalltext muted">共 ${skuOrders(s,true).length} 单</p>`;}
  showDrawer(s.name,nav+body,`sku:${id}`);
}
function transactionSummary(s:Sku){const all=skuOrders(s,true).filter(o=>o.status==='completed');return panel('成交形态 · 分开统计',table(['成交形态','#完成订单','#顾客实付 / 单','#平台补贴 / 单','#平台单均收益 / 单'],(Object.keys(forms) as Form[]).map(form=>{const subset=all.filter(o=>o.form===form),m=metrics(subset,skus);return `<tr><td>${forms[form]}</td><td class="number num">${m.n}</td><td class="number num">${m.n?money(m.paid/m.n):'—'}</td><td class="number num">${m.n?money(m.subsidy/m.n):'—'}</td><td class="number num ${tone(m.platform)}">${signed(m.platform)}</td></tr>`;}),550));}
function moneyRow(label:string,value:number|null,total=false){return `<div class="money-row ${total?'total':''}"><span>${label}</span><span class="num ${total?tone(value):''}">${value===null?'未取得':money(value)}</span></div>`;}
function orderDrawer(id:string){const o=orders.find(o=>o.id===id)!,s=skuById(o.skuId),b=ledger(o);showDrawer('订单与原始凭据',`${btn('sku-back','← 返回订单列表',s.id,'link')}<p class="subtitle">${o.id} · ${o.date} · ${forms[o.form]} · ${tag(classify(s,o.date).baoxiao?'包销':'非包销','green')}</p><div class="notice">顾客实付、商家到账和平台收益分别计算。</div><div class="detail-grid">${panel('原始订单与结算',`<div class="panel-body">${moneyRow('商品金额',o.food)}${moneyRow('顾客包装费',o.packaging)}${moneyRow('顾客配送费（归平台）',o.customerDelivery)}${moneyRow('平台补贴',o.platformSubsidy)}${moneyRow('商家补贴',o.merchantSubsidy)}${moneyRow('品牌补贴',o.brandSubsidy)}${moneyRow('顾客实付',o.paid,true)}${moneyRow('商家结算',o.settlement,true)}</div>`)}${panel('订单贡献与分母',`<div class="panel-body">${moneyRow('平台收入',b.revenue)}${moneyRow('平台变动成本（不含用户补贴）',b.variable)}${moneyRow('平台收益',b.platform,true)}${moneyRow('商家食材成本',o.foodCost)}${moneyRow('包装成本 + 退款 + 增量人工',o.packagingCost+o.refund+o.labor)}${moneyRow('商家收益',b.merchant,true)}<p class="subtitle">订单状态：${orderStatus[o.status]}。${o.status==='completed'?'完成订单计入统计，退款不删除订单。':'不计入完成订单统计。'}</p></div>`)}</div><div style="height:20px"></div><h3>订单凭据</h3><div class="panel-body">${moneyRow('商品金额',o.food)}${moneyRow('包装费',o.packaging)}${moneyRow('配送费',o.customerDelivery)}${moneyRow('平台补贴',o.platformSubsidy)}${moneyRow('商家补贴',o.merchantSubsidy)}<p class="subtitle">订单号：${o.id}<br>结算单号：${h(s.contract.settlementEvidence)}<br>凭据编号：${o.evidence}</p></div>`,'order');}

function taskDrawer(id:string){const t=tasks.find(x=>x.id===id)!,issues=executionIssues(t,tasks,role,DEMO_NOW,skuById(t.skuId));const done=['executed','rolledback'].includes(t.status);showDrawer(t.title,`<div class="statusline"><span>${t.id} · ${h(skuById(t.skuId).name)}</span>${tag(statusLabels[t.status],'amber')}</div><label class="field">当前角色<select data-role>${roles.map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select></label><div class="notice ${issues.length&&!done?'red':'green'}">${done?'已保存执行凭据，保留原始配置与审计。':issues.length?issues.map(i=>`<div>× ${h(i)}</div>`).join(''):'✓ 执行前约束通过，可以登记人工执行结果。'}</div>
    ${panel('原值、目标与情景',`<div class="panel-body">${moneyRow('原值（元/单）',t.originalFen)}${moneyRow('目标值（元/单）',t.targetFen)}${moneyRow('最高预计补贴支出',t.expectedSpend)}${moneyRow('预算',t.budgetFen)}${moneyRow('最低预计商家收益',t.merchant)}<p class="subtitle">动作：${kindLabels[t.kind]}；原始配置：${h(t.originalEvidence)}</p></div>`)}
    ${!done?`<form id="task-settings" data-id="${id}"><div class="fields"><label class="field">负责人<input name="owner" required value="${h(t.owner)}"></label><label class="field">截止日期<input type="date" name="deadline" value="${t.deadline}" required></label><label class="field">商家告知时间<input type="datetime-local" name="notice" value="${t.notice.slice(0,16)}" required></label><label class="field">活动生效时间<input type="datetime-local" name="effective" value="${t.effective.slice(0,16)}" required></label><label class="field">活动结束时间<input type="datetime-local" name="end" value="${t.end.slice(0,16)}" required></label><label class="field">预算（元）<input type="number" name="budget" value="${t.budgetFen/100}" required min="0"></label><label class="field">促销发起方<select name="initiator">${['平台','商家','品牌'].map(x=>`<option ${t.initiator===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">促销出资方<select name="funder">${['平台','商家','品牌'].map(x=>`<option ${t.funder===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="checkbox"><input name="contractAllowed" type="checkbox" ${t.contractAllowed?'checked':''}>合同允许当前动作</label><label class="checkbox"><input name="platformAllowed" type="checkbox" ${t.platformAllowed?'checked':''}>平台规则允许当前动作</label><label class="checkbox"><input name="merchantConfirmed" type="checkbox" ${t.merchantConfirmed?'checked':''}>商家已自愿确认范围、规则和生效时间</label><label class="field">退出记录 / 处理方式<textarea name="exitRecord" required>${h(t.exitRecord)}</textarea></label><button type="submit">保存任务条件（修改后重新审批）</button></form><hr class="divider"><div class="actions">${btn('approve-business',t.businessApproved?'业务已通过':'业务审批',id,'',t.businessApproved||!['业务负责人','产品管理员'].includes(role))}${btn('approve-finance',t.financeApproved?'财务已通过':'财务审批',id,'',t.financeApproved||!['财务','产品管理员'].includes(role))}</div><p class="subtitle">业务负责人确认合同、商家与规则；财务确认出资、预算和成本。两项都通过才能交给运营执行。</p><hr class="divider"><form id="execute-form" data-id="${id}"><h3>人工执行回填</h3><p class="subtitle">业务在平台后台完成操作后，登记执行人和凭据。</p><label class="field">执行人<input name="executor" required placeholder="执行人姓名"></label><label class="field">执行后凭据编号<input name="evidence" required placeholder="例如 CONFIG-AFTER-001"></label><button type="submit" class="primary" ${issues.length?'disabled':''}>登记人工执行结果</button></form>`:`<div class="notice">执行人：${h(t.executor)}<br>执行时间：${h(stamp(t.executedAt))}<br>执行后凭据：${h(t.afterEvidence)}</div>`}
    ${t.status==='executed'?`<hr class="divider"><h3>24 小时异常监控与回滚</h3><p class="subtitle">执行后 24 小时监控平台单均收益、差评、活动配置、预算、退款与履约。发现异常时恢复原配置并登记。</p><form id="rollback-form" data-id="${id}"><label class="field">回滚原因<textarea name="reason" required placeholder="例如：差评异常，暂停观察并恢复原配置。"></textarea></label><label class="field">回滚后凭据<input name="evidence" required placeholder="例如 CONFIG-ROLLBACK-001"></label><button type="submit" class="danger" ${!['运营执行','产品管理员'].includes(role)?'disabled':''}>登记人工回滚</button></form>`:t.status==='rolledback'?`<div class="notice">已恢复原始配置。回滚凭据：${h(t.rollbackEvidence)}</div>`:''}<hr class="divider"><h3>审计记录</h3>${t.audit.map(a=>`<div class="audit"><time>${h(stamp(a.at))} · ${h(a.actor)}</time>${h(a.event)}</div>`).join('')}`,`task:${id}`);}
function allocationDrawer(){const amounts=allocate(1000,[3100,1700,0]);showDrawer('一单多品：分摊算例',`<div class="notice">使用前需与商家账单核对。仅参与优惠的商品分摊；商品金额含餐盒，打包袋和配送费不进入商品优惠基数。</div><form id="allocation-form"><label class="field">订单优惠总额（元）<input name="total" type="number" min="0" step="0.01" value="10" required></label><button>重新计算</button></form><div id="allocation-result">${allocationTable(amounts,1000)}</div><p class="subtitle">只舍不入，最后一个参与商品倒算剩余分值。骑手配送成本另按订单 / 距离分摊，不混入商品优惠。</p>`,'allocation');}
function allocationTable(a:number[],total:number){return table(['商品','优惠基数','比例','承担方','分摊金额'],[['A · 饭 + 餐盒','31.00','64.5833%','平台',money(a[0]!)],['B · 饭 + 餐盒','17.00','35.4167%','平台',money(a[1]!)],['C · 不参与该优惠','0.00','0%','无',money(a[2]!)]].map(r=>`<tr>${r.map(x=>`<td class="num">${x}</td>`).join('')}</tr>`))+`<p class="equation">${money(a[0]!)} + ${money(a[1]!)} + ${money(a[2]!)} = ${money(total)} 元，逐分守恒。</p>`;}

function exportCurrent(){const rows=page==='diagnosis'?scopeSkus().filter(s=>diagnosisFilter==='全部'||diagnose(sm(s),'sku',filters.days)===diagnosisFilter).map(s=>{const m=sm(s);return [s.id,`${s.name} · ${s.city}/${s.area}`,s.store,m.n,m.platform===null?'':money(m.platform),m.merchant===null?'':money(m.merchant),m.roi?.toFixed(4)??'',labels[diagnose(m,'sku',filters.days)],m.platform===null?'平台变动成本缺失':'',m.merchant===null?'商家成本缺失':'','示例数据',UE_VERSION];}):unitRows().filter(r=>!matrixFilter||(()=>{const [k,user,period]=matrixFilter.split('|');return r.u.user===user&&r.u.period===period&&!['insufficient','missing'].includes(r.d)&&(k==='positive'?r.m.platform!>=0:k==='before'?r.m.before!<0:r.m.before!>=0&&r.m.platform!<0);})()).map(r=>[r.u.id,`${r.u.city}/${r.u.area}`,`${r.u.category}·${r.u.user}·${r.u.period} · ${r.u.channel}入口`,r.m.n,r.m.platform===null?'':money(r.m.platform),r.m.merchant===null?'':money(r.m.merchant),r.m.roi?.toFixed(4)??'',labels[r.d],r.m.platform===null?'平台变动成本缺失':'',r.m.merchant===null?'商家成本缺失':'','示例数据',UE_VERSION]);const all=[['编号','名称','范围','完成订单','平台单均UE_元','商家收益_元','补贴ROI_估算','诊断','平台UE缺失原因','商家收益缺失原因','来源','口径'],...rows];const csv='\ufeff'+all.map(row=>row.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`包销UE_${pages[page]}_${AS_OF}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已导出当前筛选结果。');}
function updateSimulation(form:HTMLFormElement){const f=new FormData(form);const id=String(f.get('sku'));if(skus.some(s=>s.id===id))selectedSku=id;simInput={kind:String(f.get('kind')) as ActionKind,targetFen:Math.round(Number(f.get('target'))*100),response:Number(f.get('response')),competitor:f.has('competitor'),oldOnly:f.has('oldOnly'),oldShare:unitById(selected().unitId).user==='老客'?1:0,budgetFen:Math.round(Number(f.get('budget'))*100),floorFen:Math.round(Number(f.get('floor'))*100),maxLossFen:Math.round(Number(f.get('loss'))*100)};}
function createTask(){const s=selected(),m=sm(s),result=simulate(m,simInput);if(result.reasons.length||diagnose(m,'sku')==='insufficient'||!classify(s).baoxiao){notify('当前测算或包销条件不满足，不能生成任务。');return;}const owner=(document.querySelector('#action-owner') as HTMLInputElement).value.trim(),deadline=(document.querySelector('#action-deadline') as HTMLInputElement).value,title=(document.querySelector('#action-title') as HTMLInputElement).value.trim();if(!owner||!deadline||!title){notify('请填写负责人、截止日期和动作说明。');return;}const id=`ACT-DEMO-${String(tasks.length+1).padStart(3,'0')}`;const t:Task={id,skuId:s.id,kind:simInput.kind,title,owner,deadline,originalFen:simInput.kind==='subsidy'?Math.round(m.subsidy/m.n):simInput.kind==='price'?Math.round(m.food/m.n):Math.round(m.rider/m.n),targetFen:simInput.kind==='subsidy'?simInput.targetFen:simInput.kind==='price'?Math.round(m.food/m.n)+simInput.targetFen:Math.round(m.rider/m.n)-simInput.targetFen,budgetFen:simInput.budgetFen,expectedSpend:Math.max(...result.rows.map(r=>r.subsidy)),merchant:Math.min(...result.rows.map(r=>r.merchant)),floorFen:simInput.floorFen,notice:'2026-11-07T12:00:00+08:00',effective:'2026-11-14T12:00:00+08:00',end:'2026-12-11T23:59:00+08:00',initiator:'平台',funder:'平台',merchantConfirmed:false,exitRecord:'',contractAllowed:false,platformAllowed:false,simulationPassed:true,businessApproved:false,financeApproved:false,status:'approval',originalEvidence:`${s.id} 四周账本 / 原始配置 DEMO-CONFIG-${id}`,afterEvidence:'',executor:'',executedAt:'',rollbackEvidence:'',audit:[{at:DEMO_NOW,actor:role,event:'创建人工任务；测算通过'}],input:structuredClone(simInput),scenarios:result.rows};tasks.push(t);const saved=persist();navigate('execution');taskDrawer(id);if(saved)notify('任务已创建。商家确认、合同和平台规则需逐项核对，修改条件后重新审批。');}
function approve(id:string,which:'business'|'finance'){const t=tasks.find(x=>x.id===id)!;if(['executed','rolledback'].includes(t.status))return;const allowed=which==='business'?['业务负责人','产品管理员']:['财务','产品管理员'];if(!allowed.includes(role)){err('当前角色不能完成这项审批。');return;}if(!t.simulationPassed){err('测算未通过，不能审批。');return;}if(which==='business'&&(!t.contractAllowed||!t.platformAllowed||!t.merchantConfirmed||!t.exitRecord.trim())){err('请先补齐合同、平台规则、商家确认和退出记录。');return;}if(which==='finance'&&(t.expectedSpend>t.budgetFen||t.merchant<t.floorFen||t.initiator==='平台'&&t.funder!=='平台')){err('预算、商家底线或出资方不满足，不能审批。');return;}if(which==='business')t.businessApproved=true;else t.financeApproved=true;t.status=t.businessApproved&&t.financeApproved?'ready':'approval';t.audit.push({at:DEMO_NOW,actor:role,event:`${which==='business'?'业务':'财务'}审批通过`});persist();render();taskDrawer(id);}

document.addEventListener('click',event=>{const target=(event.target as Element).closest<HTMLElement>('[data-action]');if(!target||target instanceof HTMLButtonElement&&target.disabled)return;event.preventDefault();const action=target.dataset.action,id=target.dataset.id??'';
  switch(action){
    case 'nav':closeDrawer();navigate(id as Page);break;
    case 'close':closeDrawer();break;
    case 'filter':{const key=target.dataset.key!;if(key==='task')taskStatus=id;else if(key==='diagnosis')diagnosisFilter=id;else if(key in filters){filters=changeScope(filters,key as keyof ScopeFilters,id,skus,units);unitFilter='';matrixFilter='';persist();}render();break;}
    case 'reset-filter':filters=defaultScope();search='';unitFilter='';matrixFilter='';diagnosisFilter='全部';taskStatus='全部';render();break;
    case 'matrix':matrixFilter=matrixFilter===id?'':id;render();break;
    case 'clear-matrix':matrixFilter='';render();break;
    case 'clear-unit':unitFilter='';render();break;
    case 'unit-drill':unitFilter=id;navigate('diagnosis');break;
    case 'sku':skuDrawer(id,'ledger');break;
    case 'detail-tab':skuDrawer(selectedSku,id);break;
    case 'sku-back':skuDrawer(id,'orders');break;
    case 'order':orderDrawer(id);break;
    case 'quote-evidence':{const [skuId,platform]=id.split('|'),q=quotes(skuById(skuId!)).find(x=>x.platform===platform)!;showDrawer(`${platform} · 报价凭据`,`${btn('quote-back','← 返回比价',skuId!,'link')}<div class="notice">报价为结构化记录，费用分担未取得，不反推平台出资。</div><pre class="evidence">${h(JSON.stringify({source:'示例数据',quality:'示例',quote:q,missingReasons:q.payable===null?{payable:'未取得可用报价'}:{}},null,2))}</pre>`,'quote');break;}
    case 'quote-back':skuDrawer(id,'competition');break;
    case 'strategy-sku':selectedSku=id;simInput.oldShare=unitById(selected().unitId).user==='老客'?1:0;closeDrawer();navigate('strategy');break;
    case 'create-task':createTask();break;
    case 'task':taskDrawer(id);break;
    case 'approve-business':approve(id,'business');break;
    case 'approve-finance':approve(id,'finance');break;
    case 'data-tab':dataTab=id;render();break;
    case 'diagnosis-source':diagnosisSource=id;render();break;
    case 'dictionary':showDrawer('指标计算说明',dictionaryPage(),'dictionary');break;
    case 'allocation':allocationDrawer();break;
    case 'export':exportCurrent();break;
    case 'baseline':{
      const m=metrics(scopeOrders(),skus,filters.days);
      const rows=[['平台单均收益',signed(m.platform)+' 元','完成订单量加权'],['客单价',m.n?money(m.paid/m.n)+' 元':'—','顾客实际支付 / 完成订单'],['平台补贴率',pct(m.subsidy,m.gmv),'平台出资 / 商品与包装成交总额'],['补贴回报',m.roi?.toFixed(2)??'—','每 1 元补贴带来的新增收益；已扣除没有补贴也会发生的订单'],['完成订单量',n(m.n)+' 单','退款原单保留；取消、未完成不计'],['用户复购率','未取得','缺少用户身份去标识的完整数据，不用订单复购标记代替'],['同品价格比','按场景查看','同店、同品、同用户、同时间、同履约才可比']];
      showDrawer('四周经营基线',`<div class="notice">连续四周：2026-10-10 至 11-06。按城市、商圈、品类、城市等级、用户、时段和流量入口查看。</div>${table(['指标','当前筛选结果','条件与限制'],rows.map(r=>`<tr>${r.map(c=>`<td class="wrap">${h(c)}</td>`).join('')}</tr>`),700)}<div class="equation">补贴前收益 ${money(m.before===null?null:m.before*m.n)} 元 − 没有补贴也会发生的订单收益 ${money(m.baselineContribution)} 元 = 补贴带来的新增收益 ${money(m.incremental)} 元。自然订单与成本按历史数据估算。</div>`,'baseline');break;
    }
    case 'goals':showDrawer('经营目标与约束',`<div class="notice">目标：四周滚动平台单均收益持续为正，同时守住商家收益底线和补贴回报。</div><div class="goal-tree"><div><strong>结果</strong>平台单均收益 / 订单 / 复购 / 补贴回报</div><div><strong>驱动</strong>客单价 / 佣金 / 配送成本 / 补贴 / 履约 / 密度 / 用户与时段结构</div><div><strong>约束</strong>商家收益 / 毛利 / 退款 / 差评 / 我方与竞对价格比 / 预算</div></div><hr class="divider"><p class="subtitle">商家收益底线为 ¥2.00/单；实际门槛、预算和审批额度需业务与财务确认。</p>`,'goals');break;
    case 'definition':showDrawer('包销品判定规则',`<div class="equation">合同覆盖 商品、区域、周期，约定结算价格与补贴分担<br>并且<br>结算单能核对价格与承担方<br>→ 包销；否则 → 非包销</div><p class="subtitle">只有两种判定。证据不足记录缺失原因，补齐后保留修订记录并重新判定。普通一口价商品不自动成为包销，包销品用券后仍属于包销。</p>`,'definition');break;
    case 'review-evidence':showDrawer('判断效果需要什么证据',`<ul class="list"><li>分组对照：把门店或商品分成调整组和未调整组，记录开始时间、订单量和观察期。</li><li>两组前后对比：比较调整组和未调整组在调整前后的变化，先确认两组原来走势接近。</li><li>相似门店对比：找一组条件接近、没有做调整的门店作为参照。</li><li>只看调整前后：只能说明发生了变化，不能证明是这次动作带来的。</li><li>还需要记录竞对、季节、供给、用户和时段的变化，以及真实执行凭据。</li></ul>`,'method');break;
    case 'about':showDrawer('数据来源',`<p class="subtitle">当前为本地示例数据，尚未连接业务数据库。包销范围、订单和结算将由业务数据表提供；审批、执行结果和回滚只保存在本机。</p><div class="actions">${btn('nav','查看数据问题','data')}${btn('reset-demo','重置记录','','danger')}</div>`,'about');break;
    case 'reset-demo':showDrawer('重置本地记录',`<div class="notice">将清除本机保存的任务和复盘记录，恢复初始数据。不会影响采集数据。</div>${btn('confirm-reset','确认重置记录','','danger')}`,'reset');break;
    case 'confirm-reset':skus=structuredClone(seedSkus);tasks=seedTasks();feedback=[];persist();closeDrawer();render();notify('本地记录已恢复。');break;
  }
});
document.addEventListener('change',event=>{const el=event.target as HTMLInputElement;if(el.matches('[data-scope]')){filters=changeScope(filters,el.dataset.scope as keyof ScopeFilters,el.value,skus,units);unitFilter='';matrixFilter='';search='';persist();render();}else if(el.id==='review-task'){reviewTaskId=el.value;render();}else if(el.matches('[data-role]')){role=el.value;render();if(currentDrawer.startsWith('task:'))taskDrawer(currentDrawer.slice(5));}else if(el.closest('#simulation-form')){const form=el.closest<HTMLFormElement>('form')!;updateSimulation(form);render();}else if(el.id==='review-method'){reviewMethod=el.value;render();}});
let searchTimer:ReturnType<typeof setTimeout>;
document.addEventListener('input',event=>{const el=event.target as HTMLInputElement;if(el.matches('[data-search]')){const value=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{search=value;const p=el.selectionStart;render();const next=app.querySelector<HTMLInputElement>('[data-search]');next?.focus();next?.setSelectionRange(p,p);},220);}});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target as HTMLFormElement;if(!form.reportValidity())return;const f=new FormData(form),id=form.dataset.id??'',text=(k:string)=>String(f.get(k)??'').trim();
  switch(form.id){
    case 'simulation-form':updateSimulation(form);render();notify('情景测算已更新。');break;

    case 'task-settings':{const t=tasks.find(x=>x.id===id)!;if(['executed','rolledback'].includes(t.status))return;t.owner=text('owner');t.deadline=text('deadline');t.notice=text('notice')+':00+08:00';t.effective=text('effective')+':00+08:00';t.end=text('end')+':00+08:00';t.budgetFen=Math.round(Number(text('budget'))*100);t.input.budgetFen=t.budgetFen;t.initiator=text('initiator') as Task['initiator'];t.funder=text('funder') as Task['funder'];t.contractAllowed=f.has('contractAllowed');t.platformAllowed=f.has('platformAllowed');t.merchantConfirmed=f.has('merchantConfirmed');t.exitRecord=text('exitRecord');const sim=simulate(sm(skuById(t.skuId),true),t.input);t.simulationPassed=sim.reasons.length===0;t.businessApproved=false;t.financeApproved=false;t.status='approval';t.audit.push({at:DEMO_NOW,actor:role,event:'修改任务条件；原审批失效，需业务与财务重新审批'});persist();render();taskDrawer(id);break;}
    case 'execute-form':{const t=tasks.find(x=>x.id===id)!;if(['executed','rolledback'].includes(t.status))return;const issues=executionIssues(t,tasks,role,DEMO_NOW,skuById(t.skuId));if(issues.length){err(issues.join('；'));return;}if(!text('executor')||!text('evidence')){err('请填写执行人和执行后凭据。');return;}t.status='executed';t.executor=text('executor');t.executedAt=DEMO_NOW;t.afterEvidence=text('evidence');t.audit.push({at:DEMO_NOW,actor:role,event:`人工执行回填：${t.executor}；凭据 ${t.afterEvidence}`});const saved=persist();render();taskDrawer(id);if(saved)notify('已保存执行回填。');break;}
    case 'rollback-form':{const t=tasks.find(x=>x.id===id)!;if(t.status!=='executed'||!['运营执行','产品管理员'].includes(role)){err('当前状态或角色不能登记回滚。');return;}if(!text('reason')||!text('evidence')){err('请填写回滚原因和凭据。');return;}t.status='rolledback';t.rollbackEvidence=text('evidence');t.audit.push({at:DEMO_NOW,actor:role,event:`人工回滚回填：${text('reason')}；恢复原值 ${money(t.originalFen)} 元；凭据 ${t.rollbackEvidence}`});const saved=persist();render();taskDrawer(id);if(saved)notify('回滚已记录，原始配置和历史审批继续保留。');break;}
    case 'review-form':feedback.push({at:new Date().toISOString(),decision:text('decision'),note:text('note'),method:text('method'),taskId:reviewTaskId||tasks.find(t=>match(skuById(t.skuId)))?.id});if(persist())notify('复盘反馈已保存，并显示在策略页。');render();break;
    case 'allocation-form':{const total=Math.round(Number(text('total'))*100);try{const a=allocate(total,[3100,1700,0]);document.querySelector('#allocation-result')!.innerHTML=allocationTable(a,total);}catch(e){err((e as Error).message);}break;}
  }
});
drawer.addEventListener('cancel',event=>{event.preventDefault();closeDrawer();});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next in pages){page=next as Page;matrixFilter='';diagnosisFilter='全部';render();}});
const initial=location.hash.slice(1);if(initial in pages)page=initial as Page;else if(initial==='registry'){page='data';dataTab='catalogue';}
installCollection({render,show:showDrawer,selectTab:tab=>{dataTab=tab;navigate('data');}});
if(new URLSearchParams(location.search).get('collection')==='1'){page='data';dataTab='collect';}
render();



